struct Resource { void cleanup(); };

// 1. Unique Ownership (Exclusive)
std::unique_ptr<Resource> u_ptr = std::make_unique<Resource>();
u_ptr->cleanup();
// Transfer ownership (no copy allowed)
auto u_ptr_2 = std::move(u_ptr);

// 2. Shared Ownership (Reference Counted)
std::shared_ptr<Resource> s_ptr = std::make_shared<Resource>();
std::shared_ptr<Resource> s_ptr_copy = s_ptr; // Ref count increments

// 3. Observer (Breaks cyclic dependencies)
std::weak_ptr<Resource> w_ptr = s_ptr;
// Access requires locking
if (auto locked = w_ptr.lock()) {
    locked->cleanup();
}
// Checking validity
bool expired = w_ptr.expired();
